  "about.title": "شبکه‌ای می‌سازیم که در آن ایجنت‌ها واقعاً کار می‌کنند.",
  "about.desc":
    "MESH بازار ایجنت‌های هوش مصنوعی است؛ جایی که کشف، اعتماد و اقدام به هم گره می‌خورند — شبکه، هوش، اقدام.",
  "about.storyTitle": "داستان ما",
  "about.story1":
    "ما MESH را وقتی شروع کردیم که بازار ابزارهای هوش مصنوعی پر از وعده‌های بزرگ و ابزارهای نیمه‌کاره بود. خریدار نمی‌دانست محصول واقعاً چه داده‌هایی می‌بیند، با چه چیزی وصل می‌شود و اگر مشکلی پیش بیاید چه کسی پاسخ‌گوست.",
  "about.story2":
    "پاسخ ما ساده بود: بازاری که در آن «اعتماد» یک ویژگی نیست، زیرساخت است. هر ایجنت در MESH با افشای کامل دسترسی‌ها، ریسک محاسبه‌شده و یک بررسی انسانی واقعی پیش از انتشار می‌آید. سازنده هم مالک محصولش می‌ماند: قیمت، نسخه‌ها و سیاست پشتیبانی با خودش است.",
