    "دسترسی رایگان، مجوزهایی را می‌شمارد که اکنون فعال‌اند و آخرین زمان اعطایشان در بازه است. سابقهٔ لغو یا اعطای دوباره به‌صورت رویداد تغییرناپذیر نگهداری نمی‌شود.",
  "creatorAnalytics.coverage.conversion":
    "تبدیل، خریدار واردشده را به بازدید قبلی همان ایجنت که پیشنهادش در این بازه پولی ثبت شده وصل می‌کند. بازدید ناشناس و رویداد قدیمیِ بدون snapshot کنار گذاشته می‌شود؛ نرخ زیر ۳۰ بازدیدکنندهٔ واجد شرایط نمایش داده نمی‌شود.",
  "creatorAnalytics.coverage.time":
    "بازه‌های ۷ و ۳۰روزه شناور و بر مبنای مدت سپری‌شده‌اند؛ همهٔ پنجره‌ها [شروع، پایان) هستند. مقایسه با بازهٔ چرخشی هم‌اندازهٔ بلافاصله قبل انجام می‌شود. حذف تکرار روزانه و بخش‌بندی نمودار بر پایهٔ تقویم تهران است.",
  "creatorAnalytics.coverage.filters":
    "این API فقط ایجنت‌های متعلق به سازندهٔ واردشده را می‌خواند و شمارش تجمیعی برمی‌گرداند. فیلتر مالک، مدیر و خزنده‌های پیکربندی‌شده در ثبت بعضی رویدادهای نمایش، بازدید، دمو و مستندات اعمال می‌شود؛ مرورگرهای خودکار دیگر و انواع رویدادهای دیگر ممکن است باقی بمانند.",
  "creatorAnalytics.coverage.sources":
    "منبع بازدید از سمت کلاینت گزارش می‌شود؛ فقط انتساب جایگاه تبلیغاتی در سرور اعتبارسنجی می‌شود.",
